const CANON_WEBHOOKS = [
  { name: 'Reply classification', events: ['lead_replied'],
    url: 'https://n8n.coldunicorn.com/webhook/replies-classification' },
  { name: 'PDCA', events: ['tag_attached', 'tag_removed'],
    url: 'https://n8n.coldunicorn.com/webhook/bison-replies-hub' },
];
// preMQL і OOO — 16/16. MQL сюди НЕ входить: він є лише в 7 із 16, і це не діра — MQL у Bison
// народжується з вбудованого тега Interested (16/16), а bison-lead-enrichment читає
// includes('interested') || includes('mql'). Створити MQL означало б дати клієнту другий,
// гірше підключений маршрут до тієї ж кваліфікації.
const CANON_TAGS = ['preMQL', 'OOO'];
const CANON_CAMPAIGNS = ['OOO automation | general', 'OOO automation | male', 'OOO automation | female'];
// Ідентичність вебхука — events + url, НІКОЛИ не назва. Вебхук UniTalk зветься
// "Reply Classification" проти "Reply classification" у решти пʼятнадцяти.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;
// n8n кладе помилку вузла як { message, error }, і error — обʼєкт. Наївний String(err) дає
// `[object Object]` — рядок, який нічого не каже.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

// Стан ДО запису. Далі або віддається як є, або доповнюється результатами створення.
const client = $('Resolve Client').first().json ?? {};
const key = $('Effective Key').first().json ?? {};

const step = (outcome, present = [], missing = [], error = null) => ({
  outcome, present, ...(missing.length ? { missing } : {}), ...(error ? { error } : {}),
});

// Кожен список може прийти кількома айтемами — /api/campaigns пагінований через links.next.
const collect = (nodeName) => {
  let items;
  try { items = $(nodeName).all(); } catch (e) { return { rows: [], error: describe(e) }; }
  const rows = [];
  let error = null;
  for (const item of items) {
    const j = item.json ?? {};
    if (j.error) { error = describe(j.message ?? j.error); continue; }
    if (Array.isArray(j.data)) rows.push(...j.data);
    else if (Array.isArray(j)) rows.push(...j);
  }
  return { rows, error };
};

const keyStep = key.key_source === 'stored' ? step('ok', ['client_sequencers.api_key'])
  : key.key_source === 'minted' ? step('created', ['minted and stored'])
  : step('missing', [], ['api_key'],
      key.mint_error ?? (isDryRun()
        ? 'no key stored; Bison has no token-list endpoint, so nothing can be reused'
        : 'mint did not run'));

const haveKey = Boolean(key.api_key);

const webhooks = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Webhooks');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((w) => hookKey(w.events, w.url));
  const missing = CANON_WEBHOOKS.map((c) => hookKey(c.events, c.url)).filter((k) => !present.includes(k));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const tags = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Tags');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((t) => String(t?.name ?? '').trim()).filter(Boolean);
  const missing = CANON_TAGS.filter((n) => !present.includes(n));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const campaigns = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Campaigns');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const names = rows.map((c) => String(c?.name ?? '').trim());
  // Дублікати показуємо явно — інакше їх видно лише у вендора.
  const present = CANON_CAMPAIGNS
    .map((n) => ({ n, count: names.filter((x) => x === n).length }))
    .filter((x) => x.count > 0)
    .map((x) => (x.count > 1 ? `${x.n} ×${x.count}` : x.n));
  const missing = CANON_CAMPAIGNS.filter((n) => !names.includes(n));
  const dup = present.some((p) => p.includes(' ×'));
  return step(
    missing.length ? 'missing' : 'ok',
    present,
    missing,
    dup ? 'duplicate OOO campaigns at the vendor — reported, never resolved by creating more' : null,
  );
})();

return [{ json: {
  client_id: $('Input').first().json.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: isDryRun(),
  resolved: ($('Resolve Workspace').first().json ?? {}).resolved ?? null,
  steps: { key: keyStep, webhooks, tags, campaigns },
} }];

// Зводимо N відповідей вендора назад в один айтем. Порядок айтемів n8n зберігає, тож i-та
// відповідь відповідає i-му запланованому елементу.
// n8n кладе помилку вузла як { message, error }, і error — обʼєкт. Наївний String(err) дає
// `[object Object]` — рядок, який нічого не каже.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const planned = $('Plan Writes').all().map((i) => i.json);
const results = $input.all().map((i) => i.json ?? {});
const created = [];
const failed = [];
planned.forEach((p, i) => {
  const r = results[i] ?? {};
  // ТІЛЬКИ statusCode. Поле status належить вендору, а не HTTP, і Number('ok') це NaN — читати
  // його як код означає зарахувати провал за успіх.
  const code = Number(r.statusCode ?? 0);
  const bad = Boolean(r.error) || code >= 400;
  if (bad) failed.push(`${p.identity} — ${describe(r.message ?? r.error) ?? 'HTTP ' + code}`);
  else created.push(p.identity);
});
return [{ json: { created, failed } }];

// n8n кладе помилку вузла як { message, error }, і error — обʼєкт. Наївний String(err) дає
// `[object Object]` — рядок, який нічого не каже.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

// Порядок тут коротший, ніж в Aimfox, і це не спрощення, а обмеження вендора: у Bison немає
// GET на токени воркспейсу, тож перепитати його неможливо. Наслідок — ключ, який змінтили й не
// зберегли, втрачено назавжди і його можна лише перевипустити. Саме це робило старе полотно:
// воно споживало data.plain_text_token усередині виконання й не писало нікуди.
const client = $('Resolve Client').first().json ?? {};

let minted = null;
let mint_error = null;
if ($('Mint Key').isExecuted) {
  const m = $('Mint Key').first().json ?? {};
  minted = m.data?.plain_text_token ?? m.plain_text_token ?? m.data?.token ?? null;
  if (!minted) mint_error = describe(m.message ?? m.error) ?? 'mint returned no token';
}

const stored = client.api_key || null;
const api_key = stored ?? minted;
const key_source = stored ? 'stored' : minted ? 'minted' : 'none';

// key_to_store не порожній лише коли ключ щойно змінтчено. Для Bison це не зручність, а єдиний
// шанс: не записати його тут означає загубити його остаточно.
return [{ json: {
  api_key,
  key_source,
  key_to_store: key_source === 'minted' ? api_key : null,
  mint_error,
} }];

// n8n кладе помилку вузла як { message, error }, і error — обʼєкт. Наївний String(err) дає
// `[object Object]` — рядок, який нічого не каже.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const out = $('Merge Outcomes').first().json;
const rec = $json ?? {};
const failed = Boolean(rec.error);
return [{ json: {
  ...out,
  recorded: !failed,
  ...(failed ? { record_error: describe(rec.message ?? rec.error) } : {}),
} }];

// Один вхід для двох тригерів. Вебхук кладе тіло в body; executeWorkflowTrigger — у корінь.
// Без цього вузла кожне $('Start') падало б на вебхучному прогоні, бо Start там не виконується.
const fromWebhook = $('Webhook').isExecuted;
const raw = fromWebhook ? ($('Webhook').first().json?.body ?? {}) : ($('Start').first().json ?? {});

// dry_run: усе, крім ЯВНОГО булевого false, — сухий прогін. Рядок 'false' теж не рахується.
// Через відкритий вебхук це важить більше, ніж через UI: тіло приходить із мережі, і ні забуте
// поле, ні хибний тип не сміють означати "пиши в систему клієнта".
return [{ json: {
  client_id: raw.client_id ?? null,
  workspace_id: raw.workspace_id ?? null,
  dry_run: raw.dry_run === false ? false : true,
  requested_by: raw.requested_by ?? null,
  via: fromWebhook ? 'webhook' : 'sub-workflow',
} }];

// Єдина форма для Record і для відповіді. Виконується і після створення, і в обхід нього.
const base = $('Build Result').first().json;
const steps = JSON.parse(JSON.stringify(base.steps));

if ($('Collect Creates').isExecuted) {
  const { created = [], failed = [] } = $('Collect Creates').first().json ?? {};
  for (const name of ['webhooks', 'tags']) {
    const st = steps[name];
    const wanted = st.missing ?? [];
    const done = wanted.filter((k) => created.includes(k));
    const bad = wanted.filter((k) => failed.some((f) => f.startsWith(k + ' —')));
    if (done.length) st.created = done;
    st.missing = wanted.filter((k) => !done.includes(k));
    if (!st.missing.length) delete st.missing;
    st.outcome = bad.length ? 'failed' : done.length ? 'created' : st.outcome;
    if (bad.length) st.error = failed.filter((f) => bad.some((k) => f.startsWith(k + ' —'))).join('; ');
  }
}

// campaigns навмисно НЕ входить у state. Провіженінг ним не володіє і створити його не може, тож
// вічний "partial" на чотирьох клієнтах означав би кнопку «Налаштувати», яка нічого не лагодить.
// Знахідка не губиться — вона лишається в steps.campaigns і видима в порталі окремим рядком.
const decided = [steps.key, steps.webhooks, steps.tags];
const good = (s) => s.outcome === 'ok' || s.outcome === 'created';
const state = decided.every(good) ? 'configured'
  : decided.every((s) => !good(s)) ? 'missing'
  : 'partial';

return [{ json: { ...base, state, steps } }];

const input = $('Input').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// Неіснуючий клієнт — помилка того, хто викликав, а не стан провіженінгу. Але сказати про це
// треба вголос: мовчазний обрив із status=success — це те, як зникли ліди Audytel.
const state = resolution.client_missing ? 'client_not_found' : 'needs_selection';
const reason = resolution.client_missing ? 'no such client, or it has no enabled emailbison connector'
  : resolution.ambiguous ? 'more than one workspace matches the client name'
  : resolution.list_error ? `could not list workspaces: ${resolution.list_error}`
  : 'no workspace matches the client name';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: $('Input').first().json.dry_run !== false,
  resolved: null,
  state,
  reason,
  candidates: resolution.candidates ?? [],
  steps: {
    key: { outcome: 'skipped' }, webhooks: { outcome: 'skipped' },
    tags: { outcome: 'skipped' }, campaigns: { outcome: 'skipped' },
  },
} }];

const CANON_WEBHOOKS = [
  { name: 'Reply classification', events: ['lead_replied'],
    url: 'https://n8n.coldunicorn.com/webhook/replies-classification' },
  { name: 'PDCA', events: ['tag_attached', 'tag_removed'],
    url: 'https://n8n.coldunicorn.com/webhook/bison-replies-hub' },
];
// preMQL і OOO — 16/16. MQL сюди НЕ входить: він є лише в 7 із 16, і це не діра — MQL у Bison
// народжується з вбудованого тега Interested (16/16), а bison-lead-enrichment читає
// includes('interested') || includes('mql'). Створити MQL означало б дати клієнту другий,
// гірше підключений маршрут до тієї ж кваліфікації.
const CANON_TAGS = ['preMQL', 'OOO'];
const CANON_CAMPAIGNS = ['OOO automation | general', 'OOO automation | male', 'OOO automation | female'];
// Ідентичність вебхука — events + url, НІКОЛИ не назва. Вебхук UniTalk зветься
// "Reply Classification" проти "Reply classification" у решти пʼятнадцяти.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;

// Один айтем на КОЖЕН відсутній елемент. Порожній масив означає, що Create Missing не виконається
// взагалі — саме так тут влаштована безпека сухого прогону.
if (isDryRun()) return [];

const s = $json.steps ?? {};
const out = [];
for (const c of CANON_WEBHOOKS) {
  const id = hookKey(c.events, c.url);
  if ((s.webhooks?.missing ?? []).includes(id)) {
    out.push({ json: { kind: 'webhook', identity: id, url: 'https://go.gheads.com/api/webhook-url',
      body: { name: c.name, url: c.url, events: c.events } } });
  }
}
for (const name of CANON_TAGS) {
  if ((s.tags?.missing ?? []).includes(name)) {
    out.push({ json: { kind: 'tag', identity: name, url: 'https://go.gheads.com/api/tags', body: { name } } });
  }
}
// Кампанії тут НЕ плануються ніколи. Їхня копія на старому полотні побайтово однакова для трьох
// кампаній, жіночим польським, із зашитим {PANIEKAMILU} — це бізнес-контент, а не наш.
return out;

